--!strict
local Players=game:GetService("Players");local ReplicatedStorage=game:GetService("ReplicatedStorage");local Config=require(ReplicatedStorage.Modules.TrackConfig);local Race=require(script.Parent.Services.RaceService);local Movement=require(script.Parent.Services.MovementModifierService);local Maps=require(script.Parent.Services.MapService);local Registry=require(script.Parent.Services.ConnectionRegistry);local remotes=require(script.Parent.Services.RemoteService).Ensure();local last:{[Player]:number}={};local tokens:{[Player]:number}={}
local function playerFrom(hit:BasePart):Player?local n:Instance?=hit;while n and n~=workspace do if n:IsA("Model")and n:FindFirstChildOfClass("Humanoid")then return Players:GetPlayerFromCharacter(n)end;n=n.Parent end;return nil end
Maps.Loaded.Event:Connect(function(matchId,map)local zones=map:FindFirstChild("OffTrackZones");if not zones then return end;local owner="Map:"..matchId;for _,zone in zones:GetChildren()do if zone:IsA("BasePart")then Registry.Register(zone.Touched:Connect(function(hit)local p=playerFrom(hit);local d=p and Race.Get(p);local now=os.clock();if not p or not d or Race.State~="Racing"or not d.IsRacing or d.IsFinished or now-(last[p]or 0)<Config.TriggerCooldown then return end;last[p]=now;local min=zone:GetAttribute("PenaltyDurationMin")or 3;local max=zone:GetAttribute("PenaltyDurationMax")or 5;local duration=min+(max-min)*math.random();local mult=zone:GetAttribute("SpeedMultiplier")or .6;tokens[p]=(tokens[p]or 0)+1;local token=tokens[p];d.ActiveEffects.WasOffTrack=true;Movement.AddModifier(p,"OffTrackPenalty",mult,duration);remotes.TrackPenaltyUpdated:FireClient(p,{active=true,duration=duration,expiresAt=workspace:GetServerTimeNow()+duration});task.delay(duration,function()if tokens[p]==token then remotes.TrackPenaltyUpdated:FireClient(p,{active=false})end end)end),owner,"Touched")end end end)
Players.PlayerRemoving:Connect(function(p)last[p]=nil;tokens[p]=nil end)
